begin;
-- Source-only central CPU allocation. No existing school_compute/GPU grant changes.
create schema if not exists cbgpu_platform_cpu;
revoke all on schema cbgpu_platform_cpu from public,anon,authenticated,service_role;
create table if not exists cbgpu_platform_cpu.allocations(school_id text primary key references cbgpu_schools.schools(id),status text not null check(status in('DISABLED','APPROVED','REVOKED')),enabled_purposes text[] not null default '{}',limits jsonb not null,expires_at timestamptz,revision integer not null default 1,updated_by uuid not null references auth.users,updated_at timestamptz not null default clock_timestamp(),check(enabled_purposes<@array['frontend','compose','latex']::text[]));
create table if not exists cbgpu_platform_cpu.pool(id boolean primary key default true check(id),status text not null default 'DISABLED'check(status in('DISABLED','APPROVED','REVOKED')),limits jsonb not null default '{"cpu_millis":0,"memory_bytes":0,"storage_bytes":0,"max_projects":0,"max_builds":0,"max_compiles":0}',revision integer not null default 0,updated_by uuid references auth.users,updated_at timestamptz);
insert into cbgpu_platform_cpu.pool(id)values(true)on conflict(id)do nothing;alter table cbgpu_platform_cpu.pool enable row level security;
create table if not exists cbgpu_platform_cpu.projects(id uuid primary key default gen_random_uuid(),school_id text not null references cbgpu_schools.schools(id),project_kind text not null check(project_kind in('frontend','compose','latex')),project_id text not null,owner_id uuid not null references auth.users,created_by uuid not null references auth.users,created_at timestamptz not null default clock_timestamp(),unique(project_kind,project_id));
create table if not exists cbgpu_platform_cpu.delegations(id uuid primary key default gen_random_uuid(),project_seal_id uuid not null unique references cbgpu_platform_cpu.projects(id),school_id text not null references cbgpu_schools.schools(id),owner_id uuid not null references auth.users,token_hash bytea not null,enabled boolean not null default false,revision integer not null default 1,enabled_purposes text[]not null default array['frontend_build','frontend_runtime'],limits jsonb not null,expires_at timestamptz,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp());
alter table cbgpu_platform_cpu.delegations enable row level security;
create table if not exists cbgpu_platform_cpu.leases(id uuid primary key default gen_random_uuid(),project_seal_id uuid not null references cbgpu_platform_cpu.projects(id),school_id text not null references cbgpu_schools.schools(id),purpose text not null check(purpose in('frontend_build','frontend_runtime','compose_build','compose_runtime','latex_compile')),job_id uuid not null,idempotency_key uuid not null,token_hash bytea not null,actor_id uuid not null references auth.users,actor_session_id uuid,automation_id uuid references cbgpu_platform_cpu.delegations(id),automation_revision integer,cpu_millis bigint not null check(cpu_millis>0),memory_bytes bigint not null check(memory_bytes>0),storage_bytes bigint not null check(storage_bytes>=0),storage_reserved_bytes bigint not null default 0 check(storage_reserved_bytes>=0),retired_at timestamptz,retirement_proof text,state text not null default 'RESERVED'check(state in('RESERVED','RUNNING','RECONCILE_REQUIRED','STORAGE_RETAINED','RELEASED')),instance_id text,created_at timestamptz not null default clock_timestamp(),started_at timestamptz,last_seen_at timestamptz,released_at timestamptz,release_proof text,unique(project_seal_id,purpose,job_id),unique(project_seal_id,purpose,idempotency_key));
do $$begin if not exists(select 1 from information_schema.columns where table_schema='cbgpu_platform_cpu'and table_name='leases'and column_name='storage_reserved_bytes')then alter table cbgpu_platform_cpu.leases add column storage_reserved_bytes bigint;update cbgpu_platform_cpu.leases set storage_reserved_bytes=storage_bytes;alter table cbgpu_platform_cpu.leases alter column storage_reserved_bytes set not null,alter column storage_reserved_bytes set default 0;end if;end$$;
alter table cbgpu_platform_cpu.leases add column if not exists retired_at timestamptz,add column if not exists retirement_proof text;
alter table cbgpu_platform_cpu.leases drop constraint if exists leases_state_check;alter table cbgpu_platform_cpu.leases add constraint leases_state_check check(state in('RESERVED','RUNNING','RECONCILE_REQUIRED','STORAGE_RETAINED','RELEASED'));
alter table cbgpu_platform_cpu.leases alter column actor_session_id drop not null,add column if not exists automation_id uuid references cbgpu_platform_cpu.delegations(id),add column if not exists automation_revision integer;
-- Preserve revoked Auth session provenance without blocking logout's physical session deletion.
create index if not exists central_cpu_active_school on cbgpu_platform_cpu.leases(school_id,state);
create table if not exists cbgpu_platform_cpu.audit(id bigint generated always as identity primary key,school_id text not null,actor_id uuid,action text not null,target_id uuid,data jsonb not null default '{}',created_at timestamptz not null default clock_timestamp());
alter table cbgpu_platform_cpu.allocations enable row level security;alter table cbgpu_platform_cpu.projects enable row level security;alter table cbgpu_platform_cpu.leases enable row level security;alter table cbgpu_platform_cpu.audit enable row level security;
revoke all on all tables in schema cbgpu_platform_cpu from public,anon,authenticated,service_role;
alter table public.cpu_projects add column if not exists allocation_school_id text references cbgpu_schools.schools(id),add column if not exists deploy_actor_session_id uuid,add column if not exists execution_mode text check(execution_mode in('UNASSIGNED_V1','CENTRAL_V1'));
alter table public.cpu_projects alter column school_id drop not null,alter column deploy_requested_at drop not null;
create or replace function cbgpu_platform_cpu.zero_limits()returns jsonb language sql immutable set search_path='' as $$select '{"cpu_millis":0,"memory_bytes":0,"storage_bytes":0,"max_projects":0,"max_builds":0,"max_compiles":0}'::jsonb$$;
create or replace function cbgpu_platform_cpu.purpose(kind text)returns text language sql immutable set search_path='' as $$select case when kind in('frontend_build','frontend_runtime')then'frontend'when kind in('compose_build','compose_runtime')then'compose'when kind='latex_compile'then'latex'end$$;
create or replace function cbgpu_platform_cpu.identity(subject uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users u join public.profiles p on p.id=u.id where u.id=subject and u.deleted_at is null and u.email_confirmed_at is not null and(u.banned_until is null or u.banned_until<=clock_timestamp())and p.account_status in('ACTIVE','PENDING_VERIFICATION','REVERIFICATION_REQUIRED'))$$;
create or replace function cbgpu_platform_cpu.session_valid(subject uuid,session uuid)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_platform_cpu.identity(subject)and exists(select 1 from auth.sessions s where s.id=session and s.user_id=subject and(s.not_after is null or s.not_after>clock_timestamp()))$$;
create or replace function cbgpu_platform_cpu.guest_valid(subject uuid,school text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_platform_cpu.identity(subject)and not exists(select 1 from cbgpu_schools.memberships blocked where blocked.user_id=subject and blocked.school_id=school and (blocked.status='SUSPENDED'or blocked.membership_type in('STUDENT','TEACHER')))and exists(select 1 from cbgpu_accounts.guest_requests g join cbgpu_schools.schools s on s.id=g.school_id where g.external_user_id=subject and g.school_id=school and s.status='APPROVED'and g.status='APPROVED'and g.starts_at<=clock_timestamp()and g.ends_at>clock_timestamp()and'school_compute'=any(g.resources)and g.reviewed_by is not null and g.reviewed_at is not null and g.reviewed_by not in(g.requester_id,g.external_user_id)and cbgpu_platform_cpu.identity(g.requester_id)and cbgpu_schools.active_member(g.requester_id,school)and exists(select 1 from cbgpu_schools.memberships sponsor where sponsor.user_id=g.requester_id and sponsor.school_id=school and sponsor.membership_type in('STUDENT','TEACHER')))$$;
create or replace function cbgpu_platform_cpu.eligible(subject uuid,school text,purpose text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_platform_cpu.identity(subject)and purpose in('frontend','compose','latex')and((cbgpu_schools.active_member(subject,school)and exists(select 1 from cbgpu_schools.memberships m where m.user_id=subject and m.school_id=school and m.membership_type in('STUDENT','TEACHER')))or cbgpu_platform_cpu.guest_valid(subject,school))and cbgpu_schools.feature_enabled(school,case when purpose='latex'then'latex'else'projects'end)$$;
create or replace function cbgpu_platform_cpu.pool_ready()returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from cbgpu_platform_cpu.pool where id and status='APPROVED')$$;
create or replace function cbgpu_platform_cpu.global_usage()returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('cpu_millis',coalesce(sum(case when state='STORAGE_RETAINED'then 0 else cpu_millis end),0),'memory_bytes',coalesce(sum(case when state='STORAGE_RETAINED'then 0 else memory_bytes end),0),'storage_bytes',coalesce(sum(storage_reserved_bytes),0),'active_projects',count(distinct project_seal_id),'active_builds',count(*)filter(where purpose in('frontend_build','compose_build')),'active_compiles',count(*)filter(where purpose='latex_compile'),'unreconciled_leases',count(*)filter(where state='RECONCILE_REQUIRED'))from cbgpu_platform_cpu.leases where state<>'RELEASED'$$;
create or replace function cbgpu_platform_cpu.global_within_limits(add_cpu bigint default 0,add_memory bigint default 0,add_storage bigint default 0,add_projects bigint default 0,add_builds bigint default 0,add_compiles bigint default 0)returns boolean language sql stable security definer set search_path='' as $$select a.status='APPROVED'and(u->>'cpu_millis')::bigint+add_cpu<=(a.limits->>'cpu_millis')::bigint and(u->>'memory_bytes')::bigint+add_memory<=(a.limits->>'memory_bytes')::bigint and(u->>'storage_bytes')::bigint+add_storage<=(a.limits->>'storage_bytes')::bigint and(u->>'active_projects')::bigint+add_projects<=(a.limits->>'max_projects')::bigint and(u->>'active_builds')::bigint+add_builds<=(a.limits->>'max_builds')::bigint and(u->>'active_compiles')::bigint+add_compiles<=(a.limits->>'max_compiles')::bigint from cbgpu_platform_cpu.pool a cross join lateral(select cbgpu_platform_cpu.global_usage()u)x where a.id$$;
create or replace function cbgpu_platform_cpu.pool_json()returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('revision',revision,'status',status,'enabled',status='APPROVED','limits',limits,'usage',cbgpu_platform_cpu.global_usage(),'updated_at',updated_at)from cbgpu_platform_cpu.pool where id$$;
create or replace function cbgpu_platform_cpu.valid_limits(lim jsonb,positive boolean)returns boolean language plpgsql immutable set search_path='' as $$declare k text;begin
 if jsonb_typeof(lim)is distinct from'object'or(select count(*)from jsonb_object_keys(lim))<>6 or exists(select 1 from jsonb_object_keys(lim)x where x not in('cpu_millis','memory_bytes','storage_bytes','max_projects','max_builds','max_compiles'))then return false;end if;
 foreach k in array array['cpu_millis','memory_bytes','storage_bytes','max_projects','max_builds','max_compiles']loop if jsonb_typeof(lim->k)is distinct from'number'or(lim->>k)!~'^[0-9]{1,16}$'or(lim->>k)::numeric>1000000000000000 then return false;end if;end loop;
 if(lim->>'cpu_millis')::bigint>1000000 or(lim->>'max_projects')::bigint>10000 or(lim->>'max_builds')::bigint>1000 or(lim->>'max_compiles')::bigint>1000 then return false;end if;
 return not positive or((lim->>'cpu_millis')::bigint>0 and(lim->>'memory_bytes')::bigint>0 and(lim->>'storage_bytes')::bigint>0 and(lim->>'max_projects')::bigint>0);end$$;
create or replace function cbgpu_platform_cpu.allowed(school text,purpose text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_platform_cpu.pool_ready()and exists(select 1 from cbgpu_platform_cpu.allocations a join cbgpu_schools.schools s on s.id=a.school_id where a.school_id=school and s.status='APPROVED'and a.status='APPROVED'and(a.expires_at is null or a.expires_at>clock_timestamp())and purpose=any(a.enabled_purposes))$$;
create or replace function cbgpu_platform_cpu.usage(school text)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('cpu_millis',coalesce(sum(case when state='STORAGE_RETAINED'then 0 else cpu_millis end),0),'memory_bytes',coalesce(sum(case when state='STORAGE_RETAINED'then 0 else memory_bytes end),0),'storage_bytes',coalesce(sum(storage_reserved_bytes),0),'active_projects',count(distinct project_seal_id),'active_builds',count(*)filter(where purpose in('frontend_build','compose_build')),'active_compiles',count(*)filter(where purpose='latex_compile'),'unreconciled_leases',count(*)filter(where state='RECONCILE_REQUIRED'))from cbgpu_platform_cpu.leases where school_id=school and state<>'RELEASED'$$;
create or replace function cbgpu_platform_cpu.within_limits(school text,add_cpu bigint default 0,add_memory bigint default 0,add_storage bigint default 0,add_projects bigint default 0,add_builds bigint default 0,add_compiles bigint default 0)returns boolean language sql stable security definer set search_path='' as $$select(u->>'cpu_millis')::bigint+add_cpu<=(a.limits->>'cpu_millis')::bigint and(u->>'memory_bytes')::bigint+add_memory<=(a.limits->>'memory_bytes')::bigint and(u->>'storage_bytes')::bigint+add_storage<=(a.limits->>'storage_bytes')::bigint and(u->>'active_projects')::bigint+add_projects<=(a.limits->>'max_projects')::bigint and(u->>'active_builds')::bigint+add_builds<=(a.limits->>'max_builds')::bigint and(u->>'active_compiles')::bigint+add_compiles<=(a.limits->>'max_compiles')::bigint from cbgpu_platform_cpu.allocations a cross join lateral(select cbgpu_platform_cpu.usage(school)u)x where a.school_id=school and cbgpu_platform_cpu.global_within_limits(add_cpu,add_memory,add_storage,add_projects,add_builds,add_compiles)$$;
create or replace function cbgpu_platform_cpu.delegation_allowed(d cbgpu_platform_cpu.delegations)returns boolean language sql stable security definer set search_path='' as $$select d.enabled and(d.expires_at is null or d.expires_at>clock_timestamp())and cbgpu_platform_cpu.eligible(d.owner_id,d.school_id,'frontend')and cbgpu_platform_cpu.allowed(d.school_id,'frontend')and exists(select 1 from cbgpu_platform_cpu.projects p where p.id=d.project_seal_id and p.owner_id=d.owner_id and p.school_id=d.school_id and p.project_kind='frontend')and exists(select 1 from cbgpu_platform_cpu.allocations a where a.school_id=d.school_id and(a.limits->>'max_builds')::bigint>=1 and not exists(select 1 from jsonb_each(d.limits)b where(b.value->>'cpu_millis')::bigint>(a.limits->>'cpu_millis')::bigint or(b.value->>'memory_bytes')::bigint>(a.limits->>'memory_bytes')::bigint or(b.value->>'storage_bytes')::bigint>(a.limits->>'storage_bytes')::bigint))$$;
create or replace function cbgpu_platform_cpu.delegation_json(d cbgpu_platform_cpu.delegations)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('delegation_id',d.id,'revision',d.revision,'enabled',d.enabled,'allowed',cbgpu_platform_cpu.delegation_allowed(d),'school_id',d.school_id,'project_id',(select project_id from cbgpu_platform_cpu.projects where id=d.project_seal_id),'enabled_purposes',d.enabled_purposes,'limits',d.limits,'expires_at',d.expires_at,'capacity_available',cbgpu_platform_cpu.within_limits(d.school_id,2000,2147483648,0,0,1,0))$$;
create or replace function cbgpu_platform_cpu.summary(school text)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('school_id',school,'revision',coalesce(a.revision,0),'status',coalesce(a.status,'DISABLED'),'enabled',coalesce(a.status='APPROVED'and(a.expires_at is null or a.expires_at>clock_timestamp()),false),'enabled_purposes',coalesce(a.enabled_purposes,'{}'),'limits',coalesce(a.limits,cbgpu_platform_cpu.zero_limits()),'usage',cbgpu_platform_cpu.usage(school),'expires_at',a.expires_at,'updated_at',a.updated_at)from(select 1)x left join cbgpu_platform_cpu.allocations a on a.school_id=school$$;
create or replace function public.cbgpu_platform_cpu_api(action text,payload jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();sid text:=payload->>'school_id';a cbgpu_platform_cpu.allocations;lim jsonb;purpose text:=payload->>'purpose';reason text;expiry timestamptz;old jsonb;purposes text[];k text;pool_revision integer;begin
 if not public.cbgpu_personal_project_identity()then raise exception 'AUTHENTICATION_REQUIRED'using errcode='42501';end if;
 if jsonb_typeof(payload)is distinct from'object'or octet_length(payload::text)>16000 then raise exception 'INVALID_CPU_REQUEST'using errcode='22023';end if;
 if action='self'then
  if exists(select 1 from jsonb_object_keys(payload)x where x<>'purpose')or purpose not in('frontend','compose','latex')or purpose is null then raise exception 'INVALID_CPU_PURPOSE'using errcode='22023';end if;
  select school_id into sid from cbgpu_schools.preferences where user_id=uid;select * into a from cbgpu_platform_cpu.allocations where school_id=sid;
  reason:=case when sid is null then'NO_SELECTED_SCHOOL'when not cbgpu_platform_cpu.identity(uid)or not((cbgpu_schools.active_member(uid,sid)and exists(select 1 from cbgpu_schools.memberships m where m.user_id=uid and m.school_id=sid and m.membership_type in('STUDENT','TEACHER')))or cbgpu_platform_cpu.guest_valid(uid,sid))then'VERIFIED_INTERNAL_MEMBER_REQUIRED'when not cbgpu_schools.feature_enabled(sid,case when purpose='latex'then'latex'else'projects'end)then'FEATURE_DISABLED'when a.school_id is null then'NO_ALLOCATION'when a.status<>'APPROVED'then'ALLOCATION_DISABLED'when not cbgpu_platform_cpu.pool_ready()then'POOL_DISABLED'when a.expires_at is not null and a.expires_at<=clock_timestamp()then'ALLOCATION_EXPIRED'when not purpose=any(a.enabled_purposes)then'PURPOSE_DISABLED'else'ALLOWED'end;
  return jsonb_build_object('school_id',sid,'purpose',purpose,'allowed',reason='ALLOWED','reason',reason,'allocation_revision',case when reason='ALLOWED'then coalesce(a.revision,0)else 0 end,'limits',case when reason='ALLOWED'then coalesce(a.limits,cbgpu_platform_cpu.zero_limits())else cbgpu_platform_cpu.zero_limits()end,'usage',case when reason='ALLOWED'then cbgpu_platform_cpu.usage(sid)else cbgpu_platform_cpu.usage(null)end,'server_time',clock_timestamp());
 end if;
 if not exists(select 1 from public.profiles where id=uid and is_admin)then raise exception 'PLATFORM_ADMIN_REQUIRED'using errcode='42501';end if;
 if action in('pool_get','pool_set')then
  if action='pool_get'then if payload<>'{}'::jsonb then raise exception 'INVALID_CPU_POOL_REQUEST'using errcode='22023';end if;return cbgpu_platform_cpu.pool_json();end if;
  if exists(select 1 from jsonb_object_keys(payload)x where x not in('revision','status','limits','confirmed','note'))or payload->'confirmed'is distinct from'true'::jsonb or payload->>'status'not in('DISABLED','APPROVED','REVOKED')or payload->>'status'is null or jsonb_typeof(payload->'note')is distinct from'string'or length(payload->>'note')not between 1 and 2000 or not cbgpu_platform_cpu.valid_limits(payload->'limits',payload->>'status'='APPROVED')then raise exception 'EXPLICIT_VALID_CPU_POOL_REVIEW_REQUIRED'using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('central-cpu:GLOBAL',0));select revision into pool_revision from cbgpu_platform_cpu.pool where id for update;if pool_revision is distinct from(payload->>'revision')::integer then raise exception 'CPU_POOL_REVISION_CONFLICT'using errcode='40001';end if;old:=cbgpu_platform_cpu.pool_json();
  update cbgpu_platform_cpu.pool set status=payload->>'status',limits=payload->'limits',revision=revision+1,updated_by=uid,updated_at=clock_timestamp()where id;
  if payload->>'status'<>'APPROVED'then update cbgpu_platform_cpu.leases set state='RECONCILE_REQUIRED'where state in('RESERVED','RUNNING','RECONCILE_REQUIRED');end if;
  insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,data)values('__PLATFORM_POOL__',uid,'GLOBAL_POOL_REVIEW',jsonb_build_object('before',old,'after',cbgpu_platform_cpu.pool_json(),'note',payload->>'note'));return cbgpu_platform_cpu.pool_json();
 end if;
 if not exists(select 1 from cbgpu_schools.schools where id=sid)then raise exception 'SCHOOL_NOT_FOUND'using errcode='P0002';end if;
 if action='get'then if exists(select 1 from jsonb_object_keys(payload)x where x<>'school_id')then raise exception 'INVALID_CPU_REQUEST'using errcode='22023';end if;return cbgpu_platform_cpu.summary(sid);end if;
 if action<>'set'or exists(select 1 from jsonb_object_keys(payload)x where x not in('school_id','revision','status','enabled_purposes','limits','expires_at','confirmed','note'))or payload->'confirmed'is distinct from'true'::jsonb or jsonb_typeof(payload->'note')is distinct from'string'or length(payload->>'note')not between 1 and 2000 then raise exception 'EXPLICIT_CPU_ALLOCATION_REVIEW_REQUIRED'using errcode='22023';end if;
 if payload->>'status'not in('DISABLED','APPROVED','REVOKED')or payload->>'status'is null or jsonb_typeof(payload->'enabled_purposes')is distinct from'array'or jsonb_typeof(payload->'limits')is distinct from'object'then raise exception 'INVALID_CPU_ALLOCATION'using errcode='22023';end if;
 select array_agg(x)into purposes from jsonb_array_elements_text(payload->'enabled_purposes')x;purposes:=coalesce(purposes,'{}');if not purposes<@array['frontend','compose','latex']::text[]or cardinality(purposes)<>(select count(distinct x)from unnest(purposes)x)then raise exception 'INVALID_CPU_PURPOSE'using errcode='22023';end if;
 lim:=payload->'limits';if (select count(*)from jsonb_object_keys(lim))<>6 or exists(select 1 from jsonb_object_keys(lim)x where x not in('cpu_millis','memory_bytes','storage_bytes','max_projects','max_builds','max_compiles'))then raise exception 'INVALID_CPU_LIMITS'using errcode='22023';end if;
 foreach k in array array['cpu_millis','memory_bytes','storage_bytes','max_projects','max_builds','max_compiles']loop if jsonb_typeof(lim->k)is distinct from'number'or(lim->>k)!~'^[0-9]{1,16}$'or(lim->>k)::numeric>1000000000000000 then raise exception 'INVALID_CPU_LIMITS'using errcode='22023';end if;end loop;
 if(lim->>'cpu_millis')::bigint>1000000 or(lim->>'max_projects')::bigint>10000 or(lim->>'max_builds')::bigint>1000 or(lim->>'max_compiles')::bigint>1000 then raise exception 'CPU_LIMITS_OUT_OF_RANGE'using errcode='22023';end if;
 if payload->>'status'='APPROVED'and(cardinality(purposes)=0 or(lim->>'cpu_millis')::bigint=0 or(lim->>'memory_bytes')::bigint=0 or(lim->>'storage_bytes')::bigint=0 or(lim->>'max_projects')::bigint=0)then raise exception 'POSITIVE_CPU_ALLOCATION_REQUIRED'using errcode='22023';end if;
 expiry:=(payload->>'expires_at')::timestamptz;if payload->>'status'='APPROVED'and expiry<=clock_timestamp()then raise exception 'CPU_ALLOCATION_ALREADY_EXPIRED'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('central-cpu:GLOBAL',0));perform pg_advisory_xact_lock(hashtextextended('central-cpu:'||sid,0));select * into a from cbgpu_platform_cpu.allocations where school_id=sid for update;
 if coalesce(a.revision,0)is distinct from(payload->>'revision')::integer then raise exception 'CPU_ALLOCATION_REVISION_CONFLICT'using errcode='40001';end if;old:=cbgpu_platform_cpu.summary(sid);
 insert into cbgpu_platform_cpu.allocations(school_id,status,enabled_purposes,limits,expires_at,updated_by)values(sid,payload->>'status',purposes,lim,expiry,uid)on conflict(school_id)do update set status=excluded.status,enabled_purposes=excluded.enabled_purposes,limits=excluded.limits,expires_at=excluded.expires_at,revision=cbgpu_platform_cpu.allocations.revision+1,updated_by=uid,updated_at=clock_timestamp();
 if payload->>'status'<>'APPROVED'then update cbgpu_platform_cpu.leases set state='RECONCILE_REQUIRED'where school_id=sid and state in('RESERVED','RUNNING','RECONCILE_REQUIRED');end if;
 insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,data)values(sid,uid,'ALLOCATION_REVIEW',jsonb_build_object('before',old,'after',cbgpu_platform_cpu.summary(sid),'note',payload->>'note'));
 return cbgpu_platform_cpu.summary(sid);
end$$;
create or replace function cbgpu_platform_cpu.lease_json(l cbgpu_platform_cpu.leases,allowed boolean default true)returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('lease_id',l.id,'job_id',l.job_id,'state',l.state,'allowed',allowed and l.state in('RESERVED','RUNNING'),'stop_required',not allowed and l.state in('RESERVED','RUNNING','RECONCILE_REQUIRED'),'purpose',l.purpose,'school_id',l.school_id,'cpu_millis',l.cpu_millis,'memory_bytes',l.memory_bytes,'storage_bytes',l.storage_bytes,'accounted_storage_bytes',l.storage_reserved_bytes,'instance_id',l.instance_id)$$;
create or replace function cbgpu_platform_cpu.execute(action text,payload jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare p cbgpu_platform_cpu.projects;l cbgpu_platform_cpu.leases;cp public.cpu_projects;d cbgpu_platform_cpu.delegations;automated boolean:=false;delegation_nonce text;delegation_expiry timestamptz;sid text;kind text;family text;owner uuid;actor uuid;session uuid;nonce text;cpu bigint;mem bigint;disk bigint;reserved_storage bigint;ok boolean;new_projects bigint;job uuid;idem uuid;proof text;instance text;begin
 if jsonb_typeof(payload)is distinct from'object'or octet_length(payload::text)>16000 then raise exception 'INVALID_CPU_SERVICE_REQUEST'using errcode='22023';end if;
 if action in('delegate_create','delegate_revoke','delegate_inspect')then
  if exists(select 1 from jsonb_object_keys(payload)x where x not in('school_id','project_kind','project_id','owner_id','actor_id','actor_session_id','delegation_id','delegation_token','delegation_nonce','expected_revision','expires_at'))then raise exception 'INVALID_CPU_DELEGATION_FIELDS'using errcode='22023';end if;
  if action='delegate_inspect'and payload?'delegation_token'then select * into d from cbgpu_platform_cpu.delegations where id=(payload->>'delegation_id')::uuid and token_hash=sha256(convert_to(payload->>'delegation_token','UTF8'));if not found then raise exception 'CPU_DELEGATION_NOT_FOUND'using errcode='P0002';end if;return cbgpu_platform_cpu.delegation_json(d);end if;
  actor:=(payload->>'actor_id')::uuid;owner:=(payload->>'owner_id')::uuid;session:=(payload->>'actor_session_id')::uuid;
  if actor is null or actor is distinct from owner or not cbgpu_platform_cpu.session_valid(owner,session)then raise exception 'FRESH_PROJECT_OWNER_REQUIRED'using errcode='42501';end if;
  if action='delegate_create'or not(payload?'delegation_id')then select * into p from cbgpu_platform_cpu.projects where project_kind='frontend'and project_id=payload->>'project_id'and owner_id=owner;else select projects.* into p from cbgpu_platform_cpu.projects projects join cbgpu_platform_cpu.delegations x on x.project_seal_id=projects.id where x.id=(payload->>'delegation_id')::uuid and projects.owner_id=owner;end if;
  if p.id is null or p.project_kind<>'frontend'or(payload?'school_id'and payload->>'school_id'<>p.school_id)then raise exception 'OWNED_FRONTEND_SEAL_REQUIRED'using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended('central-cpu:GLOBAL',0));perform pg_advisory_xact_lock(hashtextextended('central-cpu:'||p.school_id,0));select * into d from cbgpu_platform_cpu.delegations where project_seal_id=p.id for update;
  if action='delegate_inspect'then if d.id is null then return jsonb_build_object('enabled',false,'allowed',false,'revision',0);end if;return cbgpu_platform_cpu.delegation_json(d);end if;
  if action='delegate_create'then
   delegation_nonce:=payload->>'delegation_nonce';if delegation_nonce is null or delegation_nonce!~'^[0-9a-f]{64}$'then raise exception 'PRIVATE_DELEGATION_NONCE_REQUIRED'using errcode='22023';end if;
   if d.id is not null and d.token_hash=sha256(convert_to(delegation_nonce,'UTF8'))then return cbgpu_platform_cpu.delegation_json(d);end if;
   if coalesce(d.revision,0)is distinct from(payload->>'expected_revision')::integer then raise exception 'CPU_DELEGATION_REVISION_CONFLICT'using errcode='40001';end if;
   if not cbgpu_platform_cpu.eligible(owner,p.school_id,'frontend')or not cbgpu_platform_cpu.allowed(p.school_id,'frontend')then raise exception 'CENTRAL_CPU_ADMISSION_DENIED'using errcode='42501';end if;
   delegation_expiry:=(payload->>'expires_at')::timestamptz;if delegation_expiry is not null and(not isfinite(delegation_expiry)or delegation_expiry<=clock_timestamp())then raise exception 'INVALID_DELEGATION_EXPIRY'using errcode='22023';end if;
   insert into cbgpu_platform_cpu.delegations(project_seal_id,school_id,owner_id,token_hash,enabled,limits,expires_at)values(p.id,p.school_id,owner,sha256(convert_to(delegation_nonce,'UTF8')),true,'{"frontend_build":{"cpu_millis":2000,"memory_bytes":2147483648,"storage_bytes":0},"frontend_runtime":{"cpu_millis":1000,"memory_bytes":805306368,"storage_bytes":5368709120}}',delegation_expiry)on conflict(project_seal_id)do update set token_hash=excluded.token_hash,enabled=true,revision=cbgpu_platform_cpu.delegations.revision+1,limits=excluded.limits,expires_at=excluded.expires_at,updated_at=clock_timestamp()returning * into d;
   if not cbgpu_platform_cpu.delegation_allowed(d)then raise exception 'DELEGATION_LIMIT_EXCEEDS_ALLOCATION'using errcode='42501';end if;
   insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id)values(p.school_id,owner,'OWNER_AUTOMATION_ENABLED',d.id);return cbgpu_platform_cpu.delegation_json(d);
  end if;
  if d.id is null then raise exception 'CPU_DELEGATION_NOT_FOUND'using errcode='P0002';end if;
  if d.revision is distinct from(payload->>'expected_revision')::integer then raise exception 'CPU_DELEGATION_REVISION_CONFLICT'using errcode='40001';end if;
  update cbgpu_platform_cpu.delegations set enabled=false,revision=revision+1,updated_at=clock_timestamp()where id=d.id returning * into d;update cbgpu_platform_cpu.leases set state='RECONCILE_REQUIRED'where automation_id=d.id and state='RESERVED';
  insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id)values(p.school_id,owner,'OWNER_AUTOMATION_REVOKED',d.id);return cbgpu_platform_cpu.delegation_json(d);
 end if;
 if action in('seal','acquire')then
  if exists(select 1 from jsonb_object_keys(payload)x where x not in('school_id','project_kind','project_id','owner_id','actor_id','actor_session_id','purpose','job_id','idempotency_key','lease_nonce','cpu_millis','memory_bytes','storage_bytes','execution_mode','never_executed','delegation_id','delegation_token'))then raise exception 'INVALID_CPU_SERVICE_FIELDS'using errcode='22023';end if;
  sid:=payload->>'school_id';kind:=payload->>'project_kind';owner:=(payload->>'owner_id')::uuid;actor:=(payload->>'actor_id')::uuid;session:=(payload->>'actor_session_id')::uuid;
  if action='acquire'and payload?'delegation_id'then select * into d from cbgpu_platform_cpu.delegations where id=(payload->>'delegation_id')::uuid and token_hash=sha256(convert_to(payload->>'delegation_token','UTF8'));if not found then raise exception 'CPU_DELEGATION_NOT_FOUND'using errcode='P0002';end if;automated:=true;actor:=d.owner_id;session:=null;end if;
  if kind not in('frontend','compose','latex')or kind is null or owner is null or actor is null or(not automated and session is null)or payload->>'project_id'is null or not(case when kind='latex'then payload->>'project_id'~'^[0-9a-f]{24}$'else payload->>'project_id'~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'end)then raise exception 'INVALID_CPU_PROJECT_BINDING'using errcode='22023';end if;
  if(not automated and not cbgpu_platform_cpu.session_valid(actor,session))or not cbgpu_platform_cpu.eligible(actor,sid,kind)or not cbgpu_platform_cpu.eligible(owner,sid,kind)or not cbgpu_platform_cpu.allowed(sid,kind)then raise exception 'CENTRAL_CPU_ADMISSION_DENIED'using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended('central-cpu:GLOBAL',0));perform pg_advisory_xact_lock(hashtextextended('central-cpu:'||sid,0));
  select * into p from cbgpu_platform_cpu.projects where project_kind=kind and project_id=payload->>'project_id'for update;
  if automated then select * into d from cbgpu_platform_cpu.delegations where id=d.id for update;if not cbgpu_platform_cpu.delegation_allowed(d)or d.project_seal_id is distinct from p.id or d.owner_id<>owner or d.school_id<>sid or not(payload->>'purpose'=any(d.enabled_purposes))then raise exception 'CPU_AUTOMATION_SCOPE_DENIED'using errcode='42501';end if;end if;
  if action='seal'then
   if p.id is null then
    if payload->>'execution_mode'is distinct from'UNASSIGNED_V1'or payload->'never_executed'is distinct from'true'::jsonb or not exists(select 1 from cbgpu_schools.preferences where user_id=actor and school_id=sid)then raise exception 'EXPLICIT_UNASSIGNED_PROJECT_ATTACH_REQUIRED'using errcode='42501';end if;
    if kind='compose'then select * into cp from public.cpu_projects where id=(payload->>'project_id')::uuid for update;if not found or cp.user_id<>owner or cp.execution_mode is distinct from'UNASSIGNED_V1'or cp.deploy_requested_at is not null or cp.deployed_at is not null or cp.status<>'pending'then raise exception 'NEVER_EXECUTED_COMPOSE_DRAFT_REQUIRED'using errcode='42501';end if;end if;
    insert into cbgpu_platform_cpu.projects(school_id,project_kind,project_id,owner_id,created_by)values(sid,kind,payload->>'project_id',owner,actor)returning * into p;insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id)values(sid,actor,'PROJECT_SEALED',p.id);
    if kind='compose'then update public.cpu_projects set execution_mode='CENTRAL_V1',allocation_school_id=sid,school_id=sid where id=cp.id;end if;
   elsif p.school_id<>sid or p.owner_id<>owner then raise exception 'CPU_PROJECT_SEAL_IMMUTABLE'using errcode='42501';end if;
   return jsonb_build_object('allowed',true,'project_seal_id',p.id,'school_id',p.school_id,'project_kind',p.project_kind,'project_id',p.project_id,'owner_id',p.owner_id);
  end if;
  if p.id is null or p.school_id<>sid or p.owner_id<>owner then raise exception 'CPU_PROJECT_SEAL_REQUIRED'using errcode='42501';end if;
  family:=cbgpu_platform_cpu.purpose(payload->>'purpose');if family is distinct from kind then raise exception 'CPU_PURPOSE_PROJECT_MISMATCH'using errcode='22023';end if;
  nonce:=payload->>'lease_nonce';job:=(payload->>'job_id')::uuid;idem:=(payload->>'idempotency_key')::uuid;if nonce is null or nonce!~'^[0-9a-f]{64}$'or job is null or idem is null then raise exception 'CPU_PRIVATE_NONCE_REQUIRED'using errcode='22023';end if;
  foreach kind in array array['cpu_millis','memory_bytes','storage_bytes']loop if jsonb_typeof(payload->kind)is distinct from'number'or(payload->>kind)!~'^[0-9]{1,16}$'or(payload->>kind)::numeric>1000000000000000 then raise exception 'INVALID_CPU_RESERVATION'using errcode='22023';end if;end loop;
  cpu:=(payload->>'cpu_millis')::bigint;mem:=(payload->>'memory_bytes')::bigint;disk:=(payload->>'storage_bytes')::bigint;if cpu=0 or mem=0 then raise exception 'INVALID_CPU_RESERVATION'using errcode='22023';end if;
  if automated and(cpu>(d.limits#>>array[payload->>'purpose','cpu_millis'])::bigint or mem>(d.limits#>>array[payload->>'purpose','memory_bytes'])::bigint or disk>(d.limits#>>array[payload->>'purpose','storage_bytes'])::bigint)then raise exception 'CPU_AUTOMATION_BUDGET_EXCEEDED'using errcode='42501';end if;
  select * into l from cbgpu_platform_cpu.leases where project_seal_id=p.id and purpose=payload->>'purpose'and(job_id=job or idempotency_key=idem)for update;
  if found then if l.job_id<>job or l.idempotency_key<>idem or l.token_hash<>sha256(convert_to(nonce,'UTF8'))or l.actor_id<>actor or l.actor_session_id is distinct from session or l.automation_id is distinct from d.id or l.cpu_millis<>cpu or l.memory_bytes<>mem or l.storage_bytes<>disk then raise exception 'CPU_IDEMPOTENCY_CONFLICT'using errcode='23505';end if;return cbgpu_platform_cpu.lease_json(l,l.state<>'RECONCILE_REQUIRED');end if;
  new_projects:=case when exists(select 1 from cbgpu_platform_cpu.leases where project_seal_id=p.id and state<>'RELEASED')then 0 else 1 end;
  reserved_storage:=disk;if payload->>'purpose'in('frontend_runtime','compose_runtime')then select greatest(0,disk-coalesce(sum(storage_reserved_bytes),0))::bigint into reserved_storage from cbgpu_platform_cpu.leases where project_seal_id=p.id and purpose in('frontend_runtime','compose_runtime')and state<>'RELEASED';end if;
  if cbgpu_platform_cpu.within_limits(sid,cpu,mem,reserved_storage,new_projects,case when payload->>'purpose'in('frontend_build','compose_build')then 1 else 0 end,case when payload->>'purpose'='latex_compile'then 1 else 0 end)is not true then raise exception 'CENTRAL_CPU_QUOTA_EXCEEDED'using errcode='PT409';end if;
  insert into cbgpu_platform_cpu.leases(project_seal_id,school_id,purpose,job_id,idempotency_key,token_hash,actor_id,actor_session_id,automation_id,automation_revision,cpu_millis,memory_bytes,storage_bytes,storage_reserved_bytes)values(p.id,sid,payload->>'purpose',job,idem,sha256(convert_to(nonce,'UTF8')),actor,session,d.id,d.revision,cpu,mem,disk,reserved_storage)returning * into l;
  insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id,data)values(sid,actor,'LEASE_RESERVED',l.id,jsonb_build_object('purpose',l.purpose,'cpu_millis',cpu,'memory_bytes',mem,'storage_bytes',disk,'additional_storage_bytes',reserved_storage));return cbgpu_platform_cpu.lease_json(l);
 end if;
 if action not in('start','heartbeat','retire','release','inspect')or exists(select 1 from jsonb_object_keys(payload)x where x not in('lease_id','lease_token','actor_session_id','instance_id','stopped','proof','delegation_id','delegation_token'))then raise exception 'INVALID_CPU_LEASE_ACTION'using errcode='22023';end if;
 select * into l from cbgpu_platform_cpu.leases where id=(payload->>'lease_id')::uuid;if not found or l.token_hash is distinct from sha256(convert_to(payload->>'lease_token','UTF8'))then raise exception 'CPU_LEASE_NOT_FOUND'using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended('central-cpu:GLOBAL',0));perform pg_advisory_xact_lock(hashtextextended('central-cpu:'||l.school_id,0));select * into l from cbgpu_platform_cpu.leases where id=l.id for update;select * into p from cbgpu_platform_cpu.projects where id=l.project_seal_id;
 if action='inspect'then return cbgpu_platform_cpu.lease_json(l,l.state in('RESERVED','RUNNING')and(l.state='RUNNING'or cbgpu_platform_cpu.eligible(l.actor_id,l.school_id,p.project_kind))and cbgpu_platform_cpu.eligible(p.owner_id,l.school_id,p.project_kind)and cbgpu_platform_cpu.allowed(l.school_id,p.project_kind)and cbgpu_platform_cpu.within_limits(l.school_id));end if;
 instance:=payload->>'instance_id';if instance is null or instance!~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'then raise exception 'CPU_INSTANCE_BINDING_REQUIRED'using errcode='22023';end if;
 if action='retire'then
 if l.purpose not in('frontend_runtime','compose_runtime')or payload->'stopped'is distinct from'true'::jsonb or payload->>'proof'not in('PROCESS_EXITED','CONTAINER_ABSENT')or payload->>'proof'is null then raise exception 'PROVEN_RUNTIME_RETIREMENT_REQUIRED'using errcode='22023';end if;
 if l.instance_id is not null and l.instance_id<>instance then raise exception 'CPU_INSTANCE_MISMATCH'using errcode='42501';end if;
 if l.state in('RELEASED','STORAGE_RETAINED')then return cbgpu_platform_cpu.lease_json(l,false);end if;
 update cbgpu_platform_cpu.leases set state='STORAGE_RETAINED',instance_id=coalesce(instance_id,instance),retired_at=clock_timestamp(),retirement_proof=payload->>'proof'where id=l.id returning * into l;
 insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id,data)values(l.school_id,l.actor_id,'RUNTIME_RETIRED_STORAGE_RETAINED',l.id,jsonb_build_object('proof',payload->>'proof','retained_storage_bytes',l.storage_reserved_bytes));return cbgpu_platform_cpu.lease_json(l,false);
 end if;
 if action='release'then
  if l.instance_id is not null and l.instance_id<>instance then raise exception 'CPU_INSTANCE_MISMATCH'using errcode='42501';end if;
  proof:=payload->>'proof';if payload->'stopped'is distinct from'true'::jsonb or proof not in('PROCESS_EXITED','CONTAINER_ABSENT','NEVER_STARTED','PROJECT_DATA_REMOVED')or proof is null or(l.started_at is not null and proof='NEVER_STARTED')or(l.purpose in('frontend_runtime','compose_runtime')and proof<>'PROJECT_DATA_REMOVED')then raise exception 'PROVEN_CPU_RELEASE_REQUIRED'using errcode='22023';end if;
  if l.purpose in('frontend_runtime','compose_runtime')and exists(select 1 from cbgpu_platform_cpu.leases other where other.project_seal_id=l.project_seal_id and other.id<>l.id and other.state in('RESERVED','RUNNING','RECONCILE_REQUIRED'))then raise exception 'PROJECT_EXECUTION_STILL_ACTIVE'using errcode='42501';end if;
  if l.state<>'RELEASED'then update cbgpu_platform_cpu.leases set state='RELEASED',released_at=clock_timestamp(),release_proof=proof where id=l.id returning * into l;insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id,data)values(l.school_id,l.actor_id,'LEASE_RELEASED',l.id,jsonb_build_object('proof',proof));end if;return cbgpu_platform_cpu.lease_json(l,false);
 end if;
 if l.state in('RELEASED','STORAGE_RETAINED')then return cbgpu_platform_cpu.lease_json(l,false);end if;
 if l.instance_id is not null and l.instance_id<>instance then raise exception 'CPU_INSTANCE_MISMATCH'using errcode='42501';end if;
 ok:=cbgpu_platform_cpu.eligible(p.owner_id,l.school_id,p.project_kind)and cbgpu_platform_cpu.allowed(l.school_id,p.project_kind)and cbgpu_platform_cpu.within_limits(l.school_id);
 if action='start'then
  if l.state='RUNNING'then return cbgpu_platform_cpu.lease_json(l,ok);end if;
  if l.automation_id is not null then
   select * into d from cbgpu_platform_cpu.delegations where id=l.automation_id;if d.revision is distinct from l.automation_revision or not cbgpu_platform_cpu.delegation_allowed(d)then ok:=false;end if;
   if payload?'delegation_id'and(payload->>'delegation_id')::uuid is distinct from l.automation_id then ok:=false;end if;
   if payload?'delegation_token'and d.token_hash is distinct from sha256(convert_to(payload->>'delegation_token','UTF8'))then ok:=false;end if;
  else
   if not cbgpu_platform_cpu.eligible(l.actor_id,l.school_id,p.project_kind)or l.actor_session_id is distinct from(payload->>'actor_session_id')::uuid or not cbgpu_platform_cpu.session_valid(l.actor_id,l.actor_session_id)then ok:=false;end if;
  end if;
  if ok and l.state='RESERVED'then update cbgpu_platform_cpu.leases set state='RUNNING',instance_id=instance,started_at=clock_timestamp(),last_seen_at=clock_timestamp()where id=l.id returning * into l;insert into cbgpu_platform_cpu.audit(school_id,actor_id,action,target_id)values(l.school_id,l.actor_id,'LEASE_STARTED',l.id);return cbgpu_platform_cpu.lease_json(l);end if;
  if ok and l.state='RUNNING'then return cbgpu_platform_cpu.lease_json(l);end if;
 elsif l.state='RUNNING'and ok then update cbgpu_platform_cpu.leases set last_seen_at=clock_timestamp()where id=l.id returning * into l;return cbgpu_platform_cpu.lease_json(l);end if;
 update cbgpu_platform_cpu.leases set state='RECONCILE_REQUIRED'where id=l.id returning * into l;return cbgpu_platform_cpu.lease_json(l,false);
end$$;
do $$begin if not exists(select 1 from pg_roles where rolname='cbgpu_platform_cpu_executor')then create role cbgpu_platform_cpu_executor nologin noinherit nosuperuser nobypassrls;elsif exists(select 1 from pg_roles where rolname='cbgpu_platform_cpu_executor'and(rolcanlogin or rolsuper or rolbypassrls))then raise exception 'UNSAFE_CENTRAL_CPU_EXECUTOR_ROLE';end if;end$$;
create or replace function public.cbgpu_platform_cpu_service(action text,payload jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin if auth.role()is distinct from'service_role'and not(coalesce(auth.role(),'')=''and pg_has_role(session_user,'cbgpu_platform_cpu_executor','member'))then raise exception 'TRUSTED_CPU_EXECUTOR_REQUIRED'using errcode='42501';end if;return cbgpu_platform_cpu.execute(action,payload);end$$;
create or replace function public.cbgpu_platform_cpu_latex(action text,payload jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin
 if coalesce(auth.role(),'')<>''or not exists(select 1 from pg_roles where rolname='cbgpu_latex')or not pg_has_role(session_user,'cbgpu_latex','member')then raise exception 'TRUSTED_LATEX_EXECUTOR_REQUIRED'using errcode='42501';end if;
 if action in('seal','acquire')then if not(payload?'school_id')then payload:=payload||jsonb_build_object('school_id',(select school_id from cbgpu_schools.preferences where user_id=(payload->>'actor_id')::uuid));end if;if payload->>'project_kind'is distinct from'latex'or(action='acquire'and payload->>'purpose'is distinct from'latex_compile')then raise exception 'LATEX_PURPOSE_ONLY'using errcode='42501';end if;
 elsif not exists(select 1 from cbgpu_platform_cpu.leases l join cbgpu_platform_cpu.projects p on p.id=l.project_seal_id where l.id=(payload->>'lease_id')::uuid and p.project_kind='latex'and l.purpose='latex_compile')then raise exception 'LATEX_LEASE_NOT_FOUND'using errcode='P0002';end if;return cbgpu_platform_cpu.execute(action,payload);end$$;
revoke all on all functions in schema cbgpu_platform_cpu from public,anon,authenticated,service_role;
revoke all on function public.cbgpu_platform_cpu_api(text,jsonb),public.cbgpu_platform_cpu_service(text,jsonb),public.cbgpu_platform_cpu_latex(text,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.cbgpu_platform_cpu_api(text,jsonb)to authenticated;
grant execute on function public.cbgpu_platform_cpu_service(text,jsonb)to service_role,cbgpu_platform_cpu_executor;
do $$begin if exists(select 1 from pg_roles where rolname='cbgpu_latex')then grant execute on function public.cbgpu_platform_cpu_latex(text,jsonb)to cbgpu_latex;end if;end$$;

-- Additive Compose provenance; legacy rows remain NULL and keep their existing resource path.
create or replace function public.cbgpu_central_compose_request(project uuid,owner uuid,school text,actor uuid,actor_session uuid)returns boolean language sql stable security definer set search_path='' as $cpu$
select (auth.role()='service_role'or(auth.role()='authenticated'and actor=auth.uid()and actor=owner and actor_session=(auth.jwt()->>'session_id')::uuid and public.cbgpu_personal_project_identity()))
and cbgpu_platform_cpu.session_valid(actor,actor_session)and cbgpu_platform_cpu.eligible(actor,school,'compose')and cbgpu_platform_cpu.eligible(owner,school,'compose')and cbgpu_platform_cpu.allowed(school,'compose')and exists(select 1 from cbgpu_platform_cpu.projects p where p.project_kind='compose'and p.project_id=project::text and p.school_id=school and p.owner_id=owner)
$cpu$;
revoke all on function public.cbgpu_central_compose_request(uuid,uuid,text,uuid,uuid)from public,anon;grant execute on function public.cbgpu_central_compose_request(uuid,uuid,text,uuid,uuid)to authenticated,service_role;
create or replace function cbgpu_platform_cpu.guard_compose_binding()returns trigger language plpgsql security definer set search_path='' as $cpu$
declare requested boolean;actor uuid;session uuid;attaching boolean:=false;trusted boolean:=false;begin
 trusted:=auth.role()='service_role'or(coalesce(auth.role(),'')=''and pg_has_role(session_user,'cbgpu_platform_cpu_executor','member'));
 if tg_op='UPDATE'then
 if new.execution_mode is not null and(new.id<>old.id or new.user_id<>old.user_id)then raise exception 'CPU_PROJECT_IDENTITY_IMMUTABLE'using errcode='42501';end if;
 attaching:=old.execution_mode='UNASSIGNED_V1'and new.execution_mode='CENTRAL_V1'and old.allocation_school_id is null and new.allocation_school_id is not null and old.deploy_requested_at is null and old.deployed_at is null and old.status='pending'and trusted and exists(select 1 from cbgpu_platform_cpu.projects p where p.project_kind='compose'and p.project_id=new.id::text and p.owner_id=new.user_id and p.school_id=new.allocation_school_id and not exists(select 1 from cbgpu_platform_cpu.leases l where l.project_seal_id=p.id));
 if(new.allocation_school_id is distinct from old.allocation_school_id or new.execution_mode is distinct from old.execution_mode)and not coalesce(attaching,false)then raise exception 'CPU_PROJECT_SCHOOL_SEAL_IMMUTABLE'using errcode='42501';end if;
 end if;
 if new.execution_mode='UNASSIGNED_V1'then
 if new.allocation_school_id is not null or new.deploy_requested_at is not null or new.deployed_at is not null or new.status not in('pending','deleted','rejected')or new.deploy_requested_by is not null or new.deploy_actor_session_id is not null then raise exception 'UNASSIGNED_PROJECT_CANNOT_EXECUTE'using errcode='42501';end if;new.school_id:=null;return new;
 end if;
 if new.allocation_school_id is null and new.execution_mode is null then return new;end if;
 if new.execution_mode is distinct from'CENTRAL_V1'or new.allocation_school_id is null then raise exception 'CENTRAL_COMPOSE_BINDING_REQUIRED'using errcode='42501';end if;
 if new.school_id is distinct from new.allocation_school_id or new.env_vars->>'CBGPU_DEPLOY_ENGINE'is distinct from'compose'then raise exception 'CENTRAL_COMPOSE_ONLY'using errcode='42501';end if;
 if tg_op='INSERT'then requested:=new.deploy_requested_at is not null;else requested:=new.deploy_requested_at is not null and new.deploy_requested_at is distinct from old.deploy_requested_at;end if;
 if auth.role()='authenticated'then actor:=auth.uid();session:=(auth.jwt()->>'session_id')::uuid;elsif auth.role()='service_role'then actor:=new.deploy_requested_by;session:=new.deploy_actor_session_id;else actor:=new.deploy_requested_by;session:=new.deploy_actor_session_id;end if;
 if requested then
 if public.cbgpu_central_compose_request(new.id,new.user_id,new.allocation_school_id,actor,session)is not true then raise exception 'CENTRAL_COMPOSE_PERMISSION_REQUIRED'using errcode='42501';end if;new.deploy_requested_by:=actor;new.deploy_actor_session_id:=session;
 elsif tg_op='UPDATE'and new.deploy_actor_session_id is distinct from old.deploy_actor_session_id then raise exception 'CPU_DEPLOYMENT_SESSION_IMMUTABLE'using errcode='42501';
 elsif tg_op='INSERT'then
 if new.deploy_actor_session_id is not null then raise exception 'CPU_SESSION_WITHOUT_REQUEST'using errcode='42501';end if;
 if not exists(select 1 from cbgpu_platform_cpu.projects p where p.project_kind='compose'and p.project_id=new.id::text and p.school_id=new.allocation_school_id and p.owner_id=new.user_id)then raise exception 'CPU_PROJECT_SEAL_REQUIRED'using errcode='42501';end if;
 end if;return new;end$cpu$;
drop trigger if exists z_central_cpu_binding on public.cpu_projects;create trigger z_central_cpu_binding before insert or update on public.cpu_projects for each row execute function cbgpu_platform_cpu.guard_compose_binding();
-- Existing approval predicates remain authoritative for ordinary/legacy projects.
create or replace function cbgpu_accounts.guard_resource_execution()returns trigger language plpgsql set search_path='' as $cpu$
begin
 if auth.role()='service_role'or current_user in('postgres','supabase_admin')then return new;end if;
 if tg_table_name='cpu_projects'then
 if(new.deploy_requested_at is distinct from old.deploy_requested_at or new.status='approved'and old.status is distinct from'approved')and public.cbgpu_can_use_resource('school_compute')is not true and not(new.allocation_school_id is not null and new.env_vars->>'CBGPU_DEPLOY_ENGINE'='compose'and public.cbgpu_central_compose_request(new.id,new.user_id,new.allocation_school_id,auth.uid(),(auth.jwt()->>'session_id')::uuid))then raise exception 'SCHOOL_RESOURCE_PERMISSION_REQUIRED'using errcode='42501';end if;
 elsif tg_table_name='reservations'then if(new.start_time is distinct from old.start_time or new.end_time>old.end_time or new.status='approved'and old.status is distinct from'approved')and public.cbgpu_can_use_resource('gpu')is not true then raise exception 'SCHOOL_RESOURCE_PERMISSION_REQUIRED'using errcode='42501';end if;end if;return new;end$cpu$;
-- Private helper/table lookups in RLS go through a narrow self-only predicate.
create or replace function public.cbgpu_central_compose_draft(project uuid,owner uuid,school text)returns boolean language sql stable security definer set search_path='' as $cpu$select owner=auth.uid()and public.cbgpu_personal_project_identity()and cbgpu_platform_cpu.eligible(auth.uid(),school,'compose')and cbgpu_platform_cpu.allowed(school,'compose')and exists(select 1 from cbgpu_platform_cpu.projects p where p.project_kind='compose'and p.project_id=project::text and p.school_id=school and p.owner_id=owner)$cpu$;
revoke all on function public.cbgpu_central_compose_draft(uuid,uuid,text)from public,anon;grant execute on function public.cbgpu_central_compose_draft(uuid,uuid,text)to authenticated,service_role;
drop policy if exists central_cpu_compose_create on public.cpu_projects;create policy central_cpu_compose_create on public.cpu_projects for insert to authenticated with check(allocation_school_id is not null and school_id=allocation_school_id and env_vars->>'CBGPU_DEPLOY_ENGINE'='compose'and status='pending'and public.cbgpu_central_compose_draft(id,user_id,allocation_school_id));
drop policy if exists account_v2_resource_insert on public.cpu_projects;create policy account_v2_resource_insert on public.cpu_projects as restrictive for insert to authenticated with check((deploy_requested_at is null and status='pending')or public.cbgpu_can_use_resource('school_compute')or(allocation_school_id is not null and env_vars->>'CBGPU_DEPLOY_ENGINE'='compose'and public.cbgpu_central_compose_request(id,user_id,allocation_school_id,auth.uid(),(auth.jwt()->>'session_id')::uuid)));
drop policy if exists central_cpu_own_draft_create on public.cpu_projects;create policy central_cpu_own_draft_create on public.cpu_projects for insert to authenticated with check(execution_mode='UNASSIGNED_V1'and user_id=auth.uid()and status='pending'and deploy_requested_at is null and allocation_school_id is null and public.cbgpu_personal_project_identity());
drop policy if exists central_cpu_own_history_read on public.cpu_projects;create policy central_cpu_own_history_read on public.cpu_projects for select to authenticated using(execution_mode in('UNASSIGNED_V1','CENTRAL_V1')and user_id=auth.uid()and public.cbgpu_personal_project_identity());
drop policy if exists central_cpu_own_metadata_update on public.cpu_projects;create policy central_cpu_own_metadata_update on public.cpu_projects for update to authenticated using(execution_mode in('UNASSIGNED_V1','CENTRAL_V1')and user_id=auth.uid()and public.cbgpu_personal_project_identity())with check(execution_mode in('UNASSIGNED_V1','CENTRAL_V1')and user_id=auth.uid()and public.cbgpu_personal_project_identity());
drop policy if exists central_cpu_own_delete on public.cpu_projects;create policy central_cpu_own_delete on public.cpu_projects for delete to authenticated using(execution_mode in('UNASSIGNED_V1','CENTRAL_V1')and user_id=auth.uid()and public.cbgpu_personal_project_identity());

-- Derived central capability is separate from the unchanged legacy school_compute oracle.
create or replace function cbgpu_platform_cpu.context_allowed(subject uuid,school text)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from unnest(array['frontend','compose','latex'])p where cbgpu_platform_cpu.eligible(subject,school,p)and cbgpu_platform_cpu.allowed(school,p))$$;
create or replace function cbgpu_schools.context_available(subject uuid,school text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_schools.active_member(subject,school)or cbgpu_platform_cpu.context_allowed(subject,school)or exists(select 1 from cbgpu_accounts.guest_requests g where g.external_user_id=subject and g.school_id=school and g.status='APPROVED'and g.starts_at<=now()and g.ends_at>now()and exists(select 1 from unnest(g.resources)r where cbgpu_accounts.can_user_use_resource(subject,r,school)))$$;
do $$declare definition text;updated text;begin definition:=pg_get_functiondef('cbgpu_schools.resource_context(uuid,text)'::regprocedure);if position('resource_context_before_central_cpu'in definition)=0 then updated:=replace(definition,'FUNCTION cbgpu_schools.resource_context(','FUNCTION cbgpu_schools.resource_context_before_central_cpu(');if updated=definition then raise exception 'CPU_CONTEXT_SOURCE_MISMATCH';end if;execute updated;end if;end$$;
revoke all on function cbgpu_schools.resource_context_before_central_cpu(uuid,text)from public,anon,authenticated,service_role;
create or replace function cbgpu_schools.resource_context(subject uuid,school text)returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;expiry timestamptz;begin
 result:=cbgpu_schools.resource_context_before_central_cpu(subject,school);if result is null then return null;end if;
 if cbgpu_platform_cpu.context_allowed(subject,school)then
 result:=jsonb_set(result,'{resources}',coalesce(result->'resources','[]')||'"central_cpu"'::jsonb);
 if result->>'type'='GUEST'then select least(min(g.ends_at),(select expires_at from cbgpu_platform_cpu.allocations where school_id=school))into expiry from cbgpu_accounts.guest_requests g where g.external_user_id=subject and g.school_id=school and g.status='APPROVED'and g.starts_at<=clock_timestamp()and g.ends_at>clock_timestamp()and'school_compute'=any(g.resources)and cbgpu_schools.active_member(g.requester_id,school);result:=jsonb_set(result,'{expires_at}',to_jsonb(least((result->>'expires_at')::timestamptz,expiry)));end if;
 end if;return result;end$$;
create or replace function cbgpu_platform_cpu.sponsor_resource(subject uuid,resource text,school text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_accounts.can_user_use_resource(subject,resource,school)or(resource='school_compute'and cbgpu_schools.active_member(subject,school)and exists(select 1 from cbgpu_schools.memberships m where m.user_id=subject and m.school_id=school and m.membership_type in('STUDENT','TEACHER'))and cbgpu_platform_cpu.context_allowed(subject,school))$$;
do $$declare definition text;updated text;begin definition:=pg_get_functiondef('public.cbgpu_school_guest_api(text,jsonb)'::regprocedure);updated:=replace(definition,'cbgpu_accounts.can_user_use_resource(uid,resource,sid)','cbgpu_platform_cpu.sponsor_resource(uid,resource,sid)');updated:=replace(updated,'cbgpu_accounts.can_user_use_resource(g.requester_id,resource,sid)','cbgpu_platform_cpu.sponsor_resource(g.requester_id,resource,sid)');if updated=definition and position('cbgpu_platform_cpu.sponsor_resource'in definition)=0 then raise exception 'CPU_GUEST_HANDLER_SOURCE_MISMATCH';end if;execute updated;
 definition:=pg_get_functiondef('public.cbgpu_self_resource_access(text)'::regprocedure);if position('central_cpu'in definition)=0 then updated:=replace(definition,$a$'resources',resources,'reasons',reasons$a$,$b$'resources',resources||jsonb_build_object('central_cpu',cbgpu_platform_cpu.context_allowed(uid,target_school)),'reasons',reasons||jsonb_build_object('central_cpu',case when cbgpu_platform_cpu.context_allowed(uid,target_school)then'ALLOWED'else'CENTRAL_CPU_NOT_GRANTED'end)$b$);if updated=definition then raise exception 'CPU_RESOURCE_SOURCE_MISMATCH';end if;execute updated;end if;end$$;
